Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:13px;margin-bottom:2px;">Polar HF molecules &amp; an electric field</div>
<div style="color:#555;line-height:1.4;margin-bottom:6px;">
  Each molecule is a large green fluorine (&delta;&minus;) fused to a small white hydrogen (&delta;+).
</div>

<label style="font-weight:600;">Electric field</label>
<div style="display:flex;gap:4px;margin-bottom:4px;">
  <button id="btnFieldOff" class="active" style="flex:1">Off — panel (a)</button>
  <button id="btnFieldOn" style="flex:1">On — panel (b)</button>
</div>

<button id="btnPlay" style="margin-bottom:6px;">▶ Play alignment (field switches on)</button>

<label style="font-weight:600;">Field strength (relative): <span id="fsVal">0.00</span>
  <input id="fieldStrength" type="range" min="0" max="1" step="0.01" value="0">
</label>
<div style="color:#666;line-height:1.35;margin:2px 0 8px;">
  0 = thermal tumbling wins (random orientations). 1 = every dipole locks in: &delta;+ toward the &minus; plate.
</div>

<hr style="width:100%;border:0;border-top:1px solid #dcdfe3;margin:2px 0 6px;">

<label style="font-weight:600;">Guided demo</label>
<div style="display:flex;gap:4px;">
  <button id="btnPrev" style="flex:1">◀ Prev</button>
  <button id="btnNext" style="flex:1">Next ▶</button>
</div>
<div id="stepTitle" style="font-weight:600;margin-top:5px;"></div>
<div id="stepNarr" style="color:#444;line-height:1.4;"></div>
<div style="color:#777;line-height:1.35;margin-top:8px;">
  Drag the figure to swing out of the printed oblique view; “Figure view” restores it. Click a molecule or plate for an explanation.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (build exactly this) ─────────────────────────────────────
   left plate    → BoxGeometry(0.25, 8.0, 1.6)  vertex-colour vertical gradient + black EdgesGeometry outline
   right plate   → BoxGeometry(0.25, 8.0, 1.6)  identical, mirrored in X
   field region  → BoxGeometry(8.8, 8.0, 1.6)   MeshBasicMaterial cream, BackSide, opacity crossfade 0→1
   molecule ×5   → Group[ SphereGeometry(0.70) green phong  +  SphereGeometry(0.42) white phong ], centres 0.82 apart
   δ− label      → addLabel just outside the F sphere along −axis  (serif, black)
   δ+ label      → addLabel just outside the H sphere along +axis  (serif, black)
   − / + signs   → addLabel at the top inner corner of each plate (panel b only)
   E-field cue   → addLabel 'Electric field' + Line leader running down-left into the cream region
   field arrows  → 3 × [ Line + ConeGeometry(0.12,0.30) ] pointing −X, near the back wall (panel b only)
   caption       → addLabel '(a)' / '(b)' 1.2 units below the plate bottoms
──────────────────────────────────────────────────────────────────────────── */

/* ── Lighting: hemisphere + upper-left key for the glossy sphere highlights ── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x999999, 0.75));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.85);
keyLight.position.set(-4, 5, 6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.25);
fillLight.position.set(3, -2, 4);
scene.add(fillLight);

/* ── Plates ───────────────────────────────────────────────────────────────── */
const PLATE_W = 0.25, PLATE_H = 8.0, PLATE_D = 1.6;
const GAP_X = 4.5;                                   // inner faces at ±4.5

const GRAY_TOP = new THREE.Color(0xE8E8E8), GRAY_BOT = new THREE.Color(0x8C8C8C);
const KHK_TOP  = new THREE.Color(0xD6C79A), KHK_BOT  = new THREE.Color(0xA6935F);

const plateGeo = new THREE.BoxGeometry(PLATE_W, PLATE_H, PLATE_D);
function paintGradient(geo, top, bot, h) {
  const pos = geo.attributes.position;
  let attr = geo.getAttribute('color');
  if (!attr) {
    attr = new THREE.BufferAttribute(new Float32Array(pos.count * 3), 3);
    geo.setAttribute('color', attr);
  }
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = THREE.MathUtils.clamp(pos.getY(i) / h + 0.5, 0, 1);
    c.copy(bot).lerp(top, t);
    attr.setXYZ(i, c.r, c.g, c.b);
  }
  attr.needsUpdate = true;
}
paintGradient(plateGeo, GRAY_TOP, GRAY_BOT, PLATE_H);

const plateMat = new THREE.MeshPhongMaterial({ vertexColors: true, shininess: 30, specular: 0x555555 });
const edgeMat  = new THREE.LineBasicMaterial({ color: 0x000000 });
const plateEdgeGeo = new THREE.EdgesGeometry(plateGeo);

function makePlate(x) {
  const m = new THREE.Mesh(plateGeo, plateMat);
  m.position.set(x, 0, 0);
  m.add(new THREE.LineSegments(plateEdgeGeo, edgeMat));
  scene.add(m);
  return m;
}
const plateL = makePlate(-(GAP_X + PLATE_W / 2));
const plateR = makePlate(  GAP_X + PLATE_W / 2);

registerInteractive(plateL, {
  title: 'Negative plate',
  tooltip: 'Negatively charged plate (−)',
  body: 'When the field is on this plate carries excess negative charge. The δ+ hydrogen end of every HF dipole is attracted toward it, which is why all the small white spheres end up pointing left.'
});
registerInteractive(plateR, {
  title: 'Positive plate',
  tooltip: 'Positively charged plate (+)',
  body: 'This plate carries excess positive charge. The δ− fluorine end of each HF molecule is pulled toward it, so all the large green spheres face right.'
});

/* ── Cream field region (panel b) ─────────────────────────────────────────── */
const fieldMat = new THREE.MeshBasicMaterial({
  color: 0xF7ECC9, side: THREE.BackSide, transparent: true, opacity: 0, depthWrite: false
});
const fieldBox = new THREE.Mesh(new THREE.BoxGeometry(8.8, PLATE_H, PLATE_D), fieldMat);
fieldBox.renderOrder = -1;
scene.add(fieldBox);

/* ── Field-direction arrows (E points from + to −, i.e. right to left) ────── */
const arrowGroup = new THREE.Group();
const arrowMat  = new THREE.LineBasicMaterial({ color: 0xB79C57, transparent: true, opacity: 0 });
const arrowMatS = new THREE.MeshBasicMaterial({ color: 0xB79C57, transparent: true, opacity: 0 });
[2.2, 0.0, -2.2].forEach(y => {
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(3.4, y, -0.7), new THREE.Vector3(-3.2, y, -0.7)
  ]);
  arrowGroup.add(new THREE.Line(g, arrowMat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.32, 16), arrowMatS);
  cone.position.set(-3.38, y, -0.7);
  cone.rotation.z = Math.PI / 2;      // +Y → −X
  arrowGroup.add(cone);
});
scene.add(arrowGroup);

/* ── 'Electric field' leader line ─────────────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0 });
const leader = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.95, 4.70, 0.05), new THREE.Vector3(-1.85, 3.45, 0.05)
]), leaderMat);
scene.add(leader);

/* ── Five HF molecules ────────────────────────────────────────────────────── */
// panel (a): centre x, y and axis angle (deg CCW from screen-right, H end along it)
const MOL_A = [[1.3, 2.8, 45], [-2.0, 0.9, 135], [0.5, -0.3, -75], [-2.1, -2.6, -55], [1.3, -2.9, 10]];
// panel (b): centre x, y (all axes at 180°)
const MOL_B = [[2.2, 3.0], [-1.4, 1.2], [-1.4, -0.4], [1.9, -1.9], [-2.4, -3.1]];
const JIT   = [1.0, -0.72, 0.55, -1.0, 0.8];        // per-molecule residual-jitter sign/size

const R_F = 0.70, R_H = 0.42, BOND = 0.82;
const fGeo = new THREE.SphereGeometry(R_F, 40, 30);
const hGeo = new THREE.SphereGeometry(R_H, 32, 24);

const molecules = [];
for (let i = 0; i < 5; i++) {
  const g = new THREE.Group();
  const f = new THREE.Mesh(fGeo, new THREE.MeshPhongMaterial({
    color: 0x5FBB46, specular: 0xA8DC8E, shininess: 55, emissive: 0x0d2a0a, emissiveIntensity: 0.25
  }));
  f.position.set(-BOND / 2, 0, 0);
  const h = new THREE.Mesh(hGeo, new THREE.MeshPhongMaterial({
    color: 0xFFFFFF, specular: 0xFFFFFF, shininess: 80, emissive: 0x555555, emissiveIntensity: 0.18
  }));
  h.position.set(BOND / 2, 0, 0);
  g.add(f, h);
  g.position.set(MOL_A[i][0], MOL_A[i][1], 0);
  g.rotation.z = THREE.MathUtils.degToRad(MOL_A[i][2]);
  scene.add(g);
  registerInteractive(g, {
    title: 'HF dipole',
    tooltip: 'Polar HF molecule — click to explain',
    body: 'Fluorine is far more electronegative than hydrogen, so bonding electrons sit closer to F. That leaves a partial negative charge (δ−) on the green fluorine and a partial positive charge (δ+) on the white hydrogen — a permanent molecular dipole. In a field the dipole feels a torque that rotates it until δ+ faces the negative plate.'
  });
  molecules.push({ group: g, base: MOL_A[i][2] });
}

/* ── Camera (oblique / cabinet shear, pose is fixed by the scaffold) ──────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.72 });

/* ── Labels ───────────────────────────────────────────────────────────────── */
const SERIF = 'font-family:Georgia,\'Times New Roman\',serif;';
const L_MINUS = new THREE.Vector3(-(BOND / 2 + R_F + 0.45), 0, 0.05);
const L_PLUS  = new THREE.Vector3( (BOND / 2 + R_H + 0.42), 0, 0.05);

for (const m of molecules) {
  m.labMinus = addLabel(`<span style="${SERIF}">&delta;&minus;</span>`, new THREE.Vector3(), { fontSize: '17px' });
  m.labPlus  = addLabel(`<span style="${SERIF}">&delta;+</span>`,       new THREE.Vector3(), { fontSize: '17px' });
}

