const labMinusPlate = addLabel(`<span style="${SERIF}">&minus;</span>`, new THREE.Vector3(-4.12, 3.55, 0.85), { fontSize: '22px', bold: true });
const labPlusPlate  = addLabel(`<span style="${SERIF}">+</span>`,       new THREE.Vector3( 4.12, 3.55, 0.85), { fontSize: '22px', bold: true });
