// @FIGURE_CODE_BEGIN
/* ── Element spec (build exactly this) ─────────────────────────────────────
   left plate    → BoxGeometry(0.16, 8.0, 1.45, 1,40,1)  MeshBasicMaterial vertexColors
                    (strong vertical light→dark gradient + specular sheen band)
                    + black EdgesGeometry outline
   right plate   → same geometry, mirrored in X
   field region  → BoxGeometry(9.0, 8.0, 1.45)  MeshBasicMaterial cream, BackSide, opacity 0→1
   molecule ×5   → Group[ SphereGeometry(0.80) bright-green phong + SphereGeometry(0.48) WHITE phong ],
                    centres 0.94 apart so the spheres interpenetrate
   δ− label      → addLabel just outside the F sphere along −axis  (serif black, anti-collision)
   δ+ label      → addLabel just outside the H sphere along +axis  (serif black, anti-collision)
   − / + signs   → addLabel at the top inner corner of each plate (panel b only)
   E-field cue   → addLabel 'Electric field' + black Line leader into the cream region (panel b only)
   field arrows  → OPTIONAL 3 × [ Line + ConeGeometry ] pointing −X (hidden by default)
   caption       → addLabel '(a)' / '(b)' 1.2 units below the plate bottoms
──────────────────────────────────────────────────────────────────────────── */

/* ── Lighting: bright ambient so flat printed colours survive, plus an
      upper-left key for the glossy sphere highlight ────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.50));
scene.add(new THREE.HemisphereLight(0xffffff, 0xe8e8e8, 0.20));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.80);
keyLight.position.set(-3.2, 4.2, 6.0);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.20);
fillLight.position.set(3.5, -2.0, 3.0);
scene.add(fillLight);

/* ── Plates (thin shiny metal sheets) ─────────────────────────────────────── */
const PLATE_W = 0.16, PLATE_H = 8.0, PLATE_D = 1.45;
const GAP_X = 4.5;                                   // inner faces at ±4.5

const GRAY_TOP = new THREE.Color(0xFDFDFD), GRAY_BOT = new THREE.Color(0x6E6E6E);
const KHK_TOP  = new THREE.Color(0xE6D9B0), KHK_BOT  = new THREE.Color(0x968149);

const plateGeo = new THREE.BoxGeometry(PLATE_W, PLATE_H, PLATE_D, 1, 40, 1);

// Flat, lighting-independent vertical gradient (MeshBasicMaterial + vertexColors)
// with two soft sheen bands so the slab reads as polished sheet metal.
function paintGradient(geo, top, bot, h) {
  const pos = geo.attributes.position;
  const nrm = geo.attributes.normal;
  let attr = geo.getAttribute('color');
  if (!attr) {
    attr = new THREE.BufferAttribute(new Float32Array(pos.count * 3), 3);
    geo.setAttribute('color', attr);
  }
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const t = THREE.MathUtils.clamp(pos.getY(i) / h + 0.5, 0, 1);
    c.copy(bot).lerp(top, Math.pow(t, 0.72));
    const sheen = 0.26 * Math.exp(-Math.pow((t - 0.72) / 0.11, 2))
                + 0.11 * Math.exp(-Math.pow((t - 0.33) / 0.15, 2));
    const ax = Math.abs(nrm.getX(i)), ay = Math.abs(nrm.getY(i)), az = Math.abs(nrm.getZ(i));
    let f = 1.0;
    if (az > 0.5) f = 1.0;        // front sliver (faces the viewer)
    else if (ax > 0.5) f = 0.74;  // the wide receding face — darker, reads as a fold
    else if (ay > 0.5) f = 0.90;  // top / bottom caps
    attr.setXYZ(i,
      Math.min(1, c.r * f + sheen * f),
      Math.min(1, c.g * f + sheen * f),
      Math.min(1, c.b * f + sheen * f));
  }
  attr.needsUpdate = true;
}
paintGradient(plateGeo, GRAY_TOP, GRAY_BOT, PLATE_H);

const plateMat = new THREE.MeshBasicMaterial({ vertexColors: true });
const edgeMat  = new THREE.LineBasicMaterial({ color: 0x000000 });
const plateEdgeGeo = new THREE.EdgesGeometry(plateGeo);

function makePlate(x) {
  const m = new THREE.Mesh(plateGeo, plateMat);
  m.position.set(x, 0, 0);
  m.add(new THREE.LineSegments(plateEdgeGeo, edgeMat));
  scene.add(m);
  return m;
}
const plateL = makePlate(-(GAP_X + PLATE_W / 2));
const plateR = makePlate(  GAP_X + PLATE_W / 2);

registerInteractive(plateL, {
  title: 'Negative plate',
  tooltip: 'Negatively charged plate (−)',
  body: 'When the field is on this plate carries excess negative charge. The δ+ hydrogen end of every HF dipole is attracted toward it, which is why all the small white spheres end up pointing left.'
});
registerInteractive(plateR, {
  title: 'Positive plate',
  tooltip: 'Positively charged plate (+)',
  body: 'This plate carries excess positive charge. The δ− fluorine end of each HF molecule is pulled toward it, so all the large green spheres face right.'
});

/* ── Cream field region (panel b) ─────────────────────────────────────────── */
const fieldMat = new THREE.MeshBasicMaterial({
  color: 0xF7ECC9, side: THREE.BackSide, transparent: true, opacity: 0, depthWrite: false
});
const fieldBox = new THREE.Mesh(new THREE.BoxGeometry(9.0, PLATE_H, PLATE_D), fieldMat);
fieldBox.renderOrder = -1;
scene.add(fieldBox);

/* ── OPTIONAL field-direction arrows (E points + → −, i.e. right to left) ─── */
const arrowGroup = new THREE.Group();
const arrowMat  = new THREE.LineBasicMaterial({ color: 0xB79C57, transparent: true, opacity: 0 });
const arrowMatS = new THREE.MeshBasicMaterial({ color: 0xB79C57, transparent: true, opacity: 0 });
[2.3, 0.0, -2.3].forEach(y => {
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(3.6, y, -0.62), new THREE.Vector3(-3.3, y, -0.62)
  ]);
  arrowGroup.add(new THREE.Line(g, arrowMat));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.32, 16), arrowMatS);
  cone.position.set(-3.48, y, -0.62);
  cone.rotation.z = Math.PI / 2;      // +Y → −X
  arrowGroup.add(cone);
});
arrowGroup.visible = false;
scene.add(arrowGroup);

/* ── 'Electric field' leader line ─────────────────────────────────────────── */
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0 });
const leader = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-2.25, 4.45, 0.05), new THREE.Vector3(-1.62, 3.40, 0.05)
]), leaderMat);
scene.add(leader);

/* ── Five HF molecules ────────────────────────────────────────────────────── */
// panel (a): centre x, y and axis angle (deg CCW from screen-right, H end along it)
const MOL_A = [[1.85, 3.05, 45], [-2.35, 1.05, 135], [0.55, -0.45, -75], [-2.40, -2.95, -55], [1.75, -3.20, 10]];
// panel (b): centre x, y (all axes at 180°)
const MOL_B = [[2.20, 3.05], [-1.60, 1.40], [-1.60, -0.60], [1.95, -1.95], [-2.35, -3.15]];
const JIT   = [1.0, -0.72, 0.55, -1.0, 0.8];        // per-molecule residual-jitter sign/size

const R_F = 0.80, R_H = 0.48, BOND = 0.94;          // ~15% larger than the first pass
const fGeo = new THREE.SphereGeometry(R_F, 48, 34);
const hGeo = new THREE.SphereGeometry(R_H, 40, 28);

// Bright textbook green / true white. The hydrogen's emissive is a low-level
// WHITE lift (not gray), so its shaded side stays a pale #C8C8C8 and its lit
// side clips to pure white — reading white against the green fluorine.
const matF = new THREE.MeshPhongMaterial({
  color: 0x5FBB46, specular: 0xB6E8A0, shininess: 55,
  emissive: 0x1b4315, emissiveIntensity: 1.0
});
const matH = new THREE.MeshPhongMaterial({
  color: 0xFFFFFF, specular: 0xFFFFFF, shininess: 95,
  emissive: 0xFFFFFF, emissiveIntensity: 0.30
});

const molecules = [];
for (let i = 0; i < 5; i++) {
  const g = new THREE.Group();
  const f = new THREE.Mesh(fGeo, matF);
  f.position.set(-BOND / 2, 0, 0);
  const h = new THREE.Mesh(hGeo, matH);
  h.position.set(BOND / 2, 0, 0);
  g.add(f, h);
  g.position.set(MOL_A[i][0], MOL_A[i][1], 0);
  g.rotation.z = THREE.MathUtils.degToRad(MOL_A[i][2]);
  scene.add(g);
  registerInteractive(g, {
    title: 'HF dipole',
    tooltip: 'Polar HF molecule — click to explain',
    body: 'Fluorine is far more electronegative than hydrogen, so bonding electrons sit closer to F. That leaves a partial negative charge (δ−) on the green fluorine and a partial positive charge (δ+) on the white hydrogen — a permanent molecular dipole. In a field the dipole feels a torque that rotates it until δ+ faces the negative plate.'
  });
  molecules.push({ group: g, base: MOL_A[i][2] });
}

/* ── Camera (oblique / cabinet shear, pose is fixed by the scaffold) ──────── */
setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, heightFraction: 0.72 });

/* ── Labels ───────────────────────────────────────────────────────────────── */
const SERIF = 'font-family:Georgia,\'Times New Roman\',serif;';
const L_MINUS = new THREE.Vector3(-(BOND / 2 + R_F + 0.52), 0, 0.06);
const L_PLUS  = new THREE.Vector3( (BOND / 2 + R_H + 0.50), 0, 0.06);

// Hand-tuned base pixel nudges (panel a → panel b) that keep each δ label on the
// clear side of its own molecule before the anti-collision pass runs.
const OFF_A_M = [[-4, 6], [4, 6], [-10, -2], [2, 6], [-6, 4]];
const OFF_A_P = [[4, -6], [-4, -6], [8, 2], [-2, -6], [6, -4]];
const OFF_B_M = [[6, 0], [6, 0], [6, 0], [6, 0], [6, 0]];
const OFF_B_P = [[-6, 0], [-6, 0], [-6, 0], [-6, 0], [-6, 0]];

for (const m of molecules) {
  m.labMinus = addLabel(`<span style="${SERIF}">&delta;&minus;</span>`, new THREE.Vector3(), { fontSize: '17px' });
  m.labPlus  = addLabel(`<span style="${SERIF}">&delta;+</span>`,       new THREE.Vector3(), { fontSize: '17px' });
}

const labMinusPlate = addLabel(`<span style="${SERIF}">&minus;</span>`, new THREE.Vector3(-4.32, 3.78, 0.66), { fontSize: '22px', bold: true });
const labPlusPlate  = addLabel(`<span style="${SERIF}">+</span>`,       new THREE.Vector3( 4.32, 3.78, 0.66), { fontSize: '22px', bold: true });
const labField      = addLabel('Electric field', new THREE.Vector3(-2.60, 4.92, 0.05), { fontSize: '16px' });
const labCaption    = addLabel('(a)', new THREE.Vector3(0, -5.25, 0), { fontSize: '17px' });

/* ── State + controls ─────────────────────────────────────────────────────── */
const ui = {
  off:    document.getElementById('btnFieldOff'),
  on:     document.getElementById('btnFieldOn'),
  play:   document.getElementById('btnPlay'),
  slider: document.getElementById('fieldStrength'),
  val:    document.getElementById('fsVal'),
  arrows: document.getElementById('chkArrows'),
  prev:   document.getElementById('btnPrev'),
  next:   document.getElementById('btnNext'),
  title:  document.getElementById('stepTitle'),
  narr:   document.getElementById('stepNarr')
};

const state = { fieldOn: false, s: 0, visual: 0, playing: false, t0: 0 };
const molS = [0, 0, 0, 0, 0];

function syncButtons() {
  ui.off.classList.toggle('active', !state.fieldOn);
  ui.on.classList.toggle('active', state.fieldOn);
  ui.slider.value = state.s.toFixed(2);
  ui.val.textContent = state.s.toFixed(2);
}

function setField(on) {
  state.playing = false;
  state.fieldOn = on;
  state.s = on ? (state.s > 0 ? state.s : 1) : 0;
  syncButtons();
}
ui.off.addEventListener('click', () => setField(false));
ui.on.addEventListener('click',  () => setField(true));

ui.slider.addEventListener('input', () => {
  state.playing = false;
  state.s = parseFloat(ui.slider.value);
  state.fieldOn = state.s > 0;
  syncButtons();
});

ui.play.addEventListener('click', () => {
  state.fieldOn = true;
  state.s = 0;
  for (let i = 0; i < 5; i++) molS[i] = 0;
  state.playing = true;
  state.t0 = performance.now();
  syncButtons();
});

ui.arrows.addEventListener('change', () => { arrowGroup.visible = ui.arrows.checked; });

/* ── Guided demo steps ────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1 · No field — random orientations',
    narration: 'Between two uncharged plates the five HF dipoles tumble freely; their δ+/δ− ends point in five different directions, so the sample has no net polarization.',
    field: false, s: 0 },
  { title: '2 · Weak field — partial alignment',
    narration: 'Turn the field on weakly. Each molecule feels a torque toward the field direction, but thermal motion keeps the alignment loose and incomplete.',
    field: true, s: 0.3 },
  { title: '3 · Strong field — full alignment',
    narration: 'At high field strength every dipole locks in: all white δ+ hydrogens face the negative left plate and all green δ− fluorines face the positive right plate.',
    field: true, s: 1 }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = THREE.MathUtils.clamp(i, 0, STEPS.length - 1);
  const st = STEPS[stepIdx];
  state.playing = false;
  state.fieldOn = st.field;
  state.s = st.s;
  syncButtons();
  ui.title.textContent = st.title;
  ui.narr.textContent = st.narration;
}
ui.prev.addEventListener('click', () => goToStep(stepIdx - 1));
ui.next.addEventListener('click', () => goToStep(stepIdx + 1));

/* ── Alignment model ──────────────────────────────────────────────────────── */
function shortestDelta(from, to) { return ((to - from + 540) % 360) - 180; }
function angleFor(i, s) {
  const base = MOL_A[i][2];
  const aligned = base + shortestDelta(base, 180) * s;
  // residual thermal jitter: zero at s = 0 (exact panel-(a) pose) and at s = 1
  const noise = JIT[i] * 35 * (1 - s) * Math.min(1, s * 3);
  return aligned + noise;
}
const easeOutCubic = t => 1 - Math.pow(1 - t, 3);

/* ── Screen-space δ-label anti-collision ──────────────────────────────────── */
const LBL_W = 38, LBL_H = 20, MAX_PUSH = 28;
const _lp = new THREE.Vector3();
const _items = [];                        // {entry, bx, by, sx, sy}

function relaxLabels(v) {
  const W = canvas.clientWidth || 1, H = canvas.clientHeight || 1;
  _items.length = 0;
  for (let i = 0; i < 5; i++) {
    const m = molecules[i];
    const bm = [THREE.MathUtils.lerp(OFF_A_M[i][0], OFF_B_M[i][0], v),
                THREE.MathUtils.lerp(OFF_A_M[i][1], OFF_B_M[i][1], v)];
    const bp = [THREE.MathUtils.lerp(OFF_A_P[i][0], OFF_B_P[i][0], v),
                THREE.MathUtils.lerp(OFF_A_P[i][1], OFF_B_P[i][1], v)];
    [[m.labMinus, bm], [m.labPlus, bp]].forEach(([e, b]) => {
      _lp.copy(e.pos).project(camera);
      _items.push({
        entry: e, bx: b[0], by: b[1],
        sx: (_lp.x * 0.5 + 0.5) * W + b[0],
        sy: (-_lp.y * 0.5 + 0.5) * H + b[1],
        dx: 0, dy: 0
      });
    });
  }
  for (let it = 0; it < 4; it++) {
    for (let a = 0; a < _items.length; a++) {
      for (let b = a + 1; b < _items.length; b++) {
        const A = _items[a], B = _items[b];
        const ddx = (B.sx + B.dx) - (A.sx + A.dx);
        const ddy = (B.sy + B.dy) - (A.sy + A.dy);
        const ox = LBL_W - Math.abs(ddx), oy = LBL_H - Math.abs(ddy);
        if (ox <= 0 || oy <= 0) continue;
        if (oy <= ox) {
          const p = (oy / 2 + 0.5) * (ddy >= 0 ? 1 : -1);
          A.dy -= p; B.dy += p;
        } else {
          const p = (ox / 2 + 0.5) * (ddx >= 0 ? 1 : -1);
          A.dx -= p; B.dx += p;
        }
      }
    }
  }
  for (const I of _items) {
    const tx = I.bx + THREE.MathUtils.clamp(I.dx, -MAX_PUSH, MAX_PUSH);
    const ty = I.by + THREE.MathUtils.clamp(I.dy, -MAX_PUSH, MAX_PUSH);
    I.entry.offset[0] += (tx - I.entry.offset[0]) * 0.28;
    I.entry.offset[1] += (ty - I.entry.offset[1]) * 0.28;
  }
}

/* ── Per-frame update ─────────────────────────────────────────────────────── */
const _wp = new THREE.Vector3();
let lastVisual = -1;

function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();

  if (state.playing) {
    const el = (now - state.t0) / 1000;
    let done = true;
    for (let i = 0; i < 5; i++) {
      const p = THREE.MathUtils.clamp((el - i * 0.08) / 1.2, 0, 1);
      molS[i] = easeOutCubic(p);
      if (p < 1) done = false;
    }
    state.s = THREE.MathUtils.clamp(el / (1.2 + 4 * 0.08), 0, 1);
    ui.slider.value = state.s.toFixed(2);
    ui.val.textContent = state.s.toFixed(2);
    if (done) { state.playing = false; state.s = 1; syncButtons(); }
  } else {
    for (let i = 0; i < 5; i++) molS[i] += (state.s - molS[i]) * 0.15;
  }

  // crossfade panel (a) ↔ (b)
  const tv = state.fieldOn ? 1 : 0;
  state.visual += (tv - state.visual) * 0.1;
  const v = state.visual;

  if (Math.abs(v - lastVisual) > 0.002) {
    lastVisual = v;
    paintGradient(plateGeo,
      GRAY_TOP.clone().lerp(KHK_TOP, v),
      GRAY_BOT.clone().lerp(KHK_BOT, v), PLATE_H);
    fieldMat.opacity = v;
    leaderMat.opacity = v;
    labMinusPlate.div.style.opacity = v;
    labPlusPlate.div.style.opacity = v;
    labField.div.style.opacity = v;
    labCaption.div.innerHTML = v > 0.5 ? '(b)' : '(a)';
  }
  arrowMat.opacity  = v * 0.9;
  arrowMatS.opacity = v * 0.9;

  for (let i = 0; i < 5; i++) {
    const m = molecules[i];
    m.group.position.set(
      THREE.MathUtils.lerp(MOL_A[i][0], MOL_B[i][0], v),
      THREE.MathUtils.lerp(MOL_A[i][1], MOL_B[i][1], v),
      0
    );
    m.group.rotation.z = THREE.MathUtils.degToRad(angleFor(i, molS[i]));
    m.group.updateMatrixWorld(true);
    m.labMinus.pos.copy(_wp.copy(L_MINUS).applyMatrix4(m.group.matrixWorld));
    m.labPlus.pos.copy(_wp.copy(L_PLUS).applyMatrix4(m.group.matrixWorld));
  }

  relaxLabels(v);
}
tick();

syncButtons();
goToStep(0);
